import java.io.*;import java.net.URI;import java.nio.file.*;import java.util.*;import javax.tools.*;
/** Java source launcher and in-memory compiler; never emits class files. */
public final class PrototypeRunner {
 static final class Source extends SimpleJavaFileObject{final String value;Source(String n,Path p)throws IOException{super(URI.create("string:///"+n.replace('.','/')+Kind.SOURCE.extension),Kind.SOURCE);value=Files.readString(p);}public CharSequence getCharContent(boolean ignored){return value;}}
 static final class Bytes extends SimpleJavaFileObject{final ByteArrayOutputStream out=new ByteArrayOutputStream();Bytes(String n,Kind k){super(URI.create("memory:///"+n.replace('.','/')+k.extension),k);}public OutputStream openOutputStream(){return out;}}
 public static void main(String[] a)throws Exception{JavaCompiler c=ToolProvider.getSystemJavaCompiler();if(c==null)throw new IllegalStateException("JDK required");Map<String,Bytes> entries=new HashMap<>();DiagnosticCollector<JavaFileObject>d=new DiagnosticCollector<>();try(StandardJavaFileManager std=c.getStandardFileManager(d,null,null)){JavaFileManager mem=new ForwardingJavaFileManager<StandardJavaFileManager>(std){public JavaFileObject getJavaFileForOutput(Location l,String n,JavaFileObject.Kind k,FileObject s){Bytes b=new Bytes(n,k);entries.put(n,b);return b;}public ClassLoader getClassLoader(Location l){return new ClassLoader(PrototypeRunner.class.getClassLoader()){protected Class<?> findClass(String n)throws ClassNotFoundException{Bytes b=entries.get(n);if(b==null)throw new ClassNotFoundException(n);byte[] v=b.out.toByteArray();return defineClass(n,v,0,v.length);}};}};List<JavaFileObject> src=List.of(new Source("org.wangshu.ime.BoundEditorPrototype",Path.of(a[0])),new Source("org.wangshu.ime.BoundEditorChecks",Path.of(a[1])));if(!c.getTask(null,mem,d,List.of("-proc:none"),null,src).call()){for(var x:d.getDiagnostics())System.err.println(x);System.exit(2);}try{mem.getClassLoader(StandardLocation.CLASS_OUTPUT).loadClass("org.wangshu.ime.BoundEditorChecks").getMethod("main",String[].class).invoke(null,(Object)new String[0]);}catch(java.lang.reflect.InvocationTargetException e){e.getCause().printStackTrace();System.exit(1);}}}
}
